'use strict';

const {esc}=require('../utils.cjs');
const {getWorkspace}=require('./state.cjs');
const {phaseAConfigForWorkspace}=require('../phase-a-config.cjs');
const {signalRubric}=require('../signal-rubric.cjs');
const {shell}=require('./pages.cjs');
const {activeTriggers}=require('../decisioning.cjs');
const {todaySections,whyNow,latestTrigger}=require('../account-lifecycle.cjs');
const {approvedSellerClaims,draftsForAccount,receiptedActiveTriggers}=require('../outreach-drafts.cjs');
const {buildDiscoveryTasks,seedCandidates}=require('../company-discovery.cjs');
const {discoveryStrategy}=require('../discovery-runner.cjs');
const {buildTriggerFirstTasks}=require('../trigger-first-discovery.cjs');
