  const segmentView=`<section class="universe-builder"><div class="universe-builder-head"><div><span class="ss-kicker">Saved ICP plan</span><h2>Configured discovery segments</h2><p>Read-only view of this workspace’s saved segments. Edit them in the seller profile.</p></div><a class="ss-btn" href="/onboarding/profile">Edit ICP</a></div><div class="universe-segments">${segmentCards||'<div class="ss-empty">No discovery segments are configured.</div>'}</div></section>`;
