  const displayed=allSections.map(([name,accounts,description])=>{let filtered=accounts.filter(account=>!q||searchText(account).includes(q));filtered=defaultSortAccounts(filtered,sort);return {name,accounts:filtered,allCount:accounts.length,description};});
  const skipped=(workspace.accounts||[]).filter(row=>row.status==='skipped').length,killed=(workspace.accounts||[]).filter(accountIsKilled).length;
