  const runLine=run=>run?`${String(run.status||'Unknown').replaceAll('_',' ')} · ${run.serperQueries??'—'} Serper queries`:'Not run yet';
  const operations=`<details class="panel fold today-operations"><summary>Prepare or refresh the queue</summary><div class="operations-grid"><section><h2>Prepare demo</h2><p>For an owner-approved seller, this background job discovers prospects and refreshes public evidence inside its configured limit. It never calls OpenAI.</p><form method="post" action="/prepare-demo"><input type="hidden" name="workspaceId" value="${esc(workspace.id)}"><button class="ss-btn primary" ${canPrepare?'':'disabled'}>Prepare demo</button></form>${canPrepare?'':'<p class="muted">This action is available after the seller profile is approved.</p>'}<p><b>Latest run:</b> ${esc(runLine(prepare))}</p></section><section><h2>Refresh all discovered accounts</h2><p>Runs guarded public collectors as a background job. Missing signals stay unknown and low-confidence.</p><form method="post" action="/accounts/refresh-all"><input type="hidden" name="workspaceId" value="${esc(workspace.id)}"><button class="ss-btn">Refresh all</button></form><p><b>Latest run:</b> ${esc(runLine(refresh))}</p></section></div></details>`;
  const [actNow,worthResearching,needsReview]=displayed,briefs=displayed.map(section=>todayBriefCard(section,config)).join(''),actNowId='today-section-act-now',actNowCards=actNow.accounts.map((account,index)=>todayCard(account,index,config,now)).join(''),actNowList=`<section class="today-list" id="${actNowId}"><div class="work-section-head"><div><span>Seller work queue</span><h2>Act now</h2></div><b>${esc(String(actNow.accounts.length))}${actNow.accounts.length!==actNow.allCount?` / ${esc(String(actNow.allCount))}`:''}</b></div>${actNowCards||`<div class="today-empty"><h2>No accounts ready to act on</h2><p>Act now requires a current trigger receipt and a known company tier. Good-fit and review records stay in their own sections.</p><div><a class="ss-btn" href="/results">Review Results</a><a class="ss-btn primary" href="/discovery">Open Discovery</a></div></div>`}</section>`;
