  const errorMarkup=args.error?`<div class="notice" role="alert">${esc(args.error)}</div>`:'';
  const body=`<div class="ss-page today-page"><header class="today-header"><div><div class="ss-kicker">Seller workday</div><h1 class="ss-title">Today</h1><p class="ss-subtitle">Daily Brief first: what is ready now, what is worth researching, and what needs review before moving forward.</p></div><div class="ss-actions"><a class="ss-btn" href="/results">Results</a><a class="ss-btn" href="/accounts">All accounts</a></div></header>${errorMarkup}<section class="today-targets">${kpis.map(([label,value])=>`<article><strong>${esc(String(value))}</strong><span>${esc(label)}</span></article>`).join('')}</section><section class="daily-brief-grid">${briefs}</section>${toolbar}${topProspects}${actNowList}<div class="today-followups">${todaySecondarySection(worthResearching,config)}${todaySecondarySection(needsReview,config)}</div>${operations}</div>`;
